"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9234],{46895:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"MemoryStoreService","desc":"Drop-in replacement for [MemoryStoreService] that swaps in a no-op mock when the\\ngame is running locally.\\n\\nMemory stores are unavailable in an unpublished place (`game.PlaceId == 0`), where\\ntouching the real service errors. Requiring this module instead lets queue and\\nsorted-map code run unchanged in Studio: the mock satisfies the same interface but\\nstores nothing, so reads always come back empty and writes are discarded.\\n\\n```lua\\nlocal MemoryStoreService = require(ReplicatedStorage.Shared.Modules.MemoryStoreService)\\n\\nlocal queue = MemoryStoreService:GetQueue(\\"Matchmaking\\")\\n```\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":21,"path":"src/Shared/Modules/MemoryStoreService.luau"}}')}}]);